  { key: '7summits', label: '7 Summits' },
  { key: '8000m', label: '8000m' },
  { key: '14ers', label: '14ers' },
  { key: 'alps', label: 'Alps' },
  { key: 'andes', label: 'Andes' },
  { key: 'himalaya', label: 'Himalaya' },
  { key: 'other', label: 'World' },
];

type SortOption = 'name' | 'elevation_desc' | 'elevation_asc';

